/// The C library's classic rand() recurrence, so the plain text can be rebuilt here.
func lcgBytes(_ n: Int, seed: UInt32) -> [UInt8] {
    var x = seed
    return (0 ..< n).map { _ in
        x = x &* 1_103_515_245 &+ 12345
        return UInt8((x >> 16) & 0xFF)
    }
}

